// IEEE 754: Widening Conversion (float to double)
// Guaranteed exact conversion.
float f_src = 12.34F;
double d_dst = f_src; // Trivial padding/copy

// Narrowing Conversion (double to float)
// Requires rounding based on FE_TONEAREST or runtime setting.
double d_large = 1.0000000000000001;
float f_narrow = static_cast<float>(d_large); // Precision loss possible

// Conversion involving long double
// long double size is implementation-defined (often 80-bit x86 extended)
long double ld_val = 1234.5L;
double d_from_ld = ld_val;

// Standard promotion in expressions
float f1 = 1.0F;
double d_calc = f1 * 2.5; // f1 promoted to double before multiplication
